import React, { useState } from "react";
import "./BudgetLimits.css";

function BudgetLimits({ data = {}, updateData, onNext }) {
  // ✅ Safe fallback so Object.keys never crashes
  const priorities = data.spendingPriorities || {};

  // ✅ Only categories with priority >= 3
  const activeCategories = Object.keys(priorities).filter(
    (cat) => priorities[cat] >= 3
  );

  const [limits, setLimits] = useState({});

  const handleChange = (category, value) => {
    setLimits(prev => ({
      ...prev,
      [category]: value
    }));
  };

  const handleSubmit = () => {
    updateData({ budgetLimits: limits });
    onNext();
  };

  return (
    <div className="budget-container">
      <div className="budget-card">
        <h2 className="budget-title">Set Monthly Budget Limits</h2>

        {activeCategories.length === 0 ? (
          <p>No categories selected with high priority.</p>
        ) : (
          activeCategories.map((category) => (
            <div key={category} className="form-group">
              <label className="form-label">{category}</label>
              <input
                type="number"
                className="form-input"
                placeholder="Enter amount"
                onChange={(e) => handleChange(category, e.target.value)}
              />
            </div>
          ))
        )}

        <button className="next-button" onClick={handleSubmit}>
          Save Budget
        </button>
      </div>
    </div>
  );
}

export default BudgetLimits;
